class HL7Ingestor:
    _segment_schema = {}  # shared across all instances; warmed at startup, mutated at runtime

    def __init__(self, site_id, strict=False):
        self.site_id = site_id
        self.strict = strict
        self.errors = []

    @classmethod
    def register_segment(cls, seg_id, fields):
        cls._segment_schema[seg_id] = fields

    def ingest(self, raw):
        self.errors = []
        segments = [s for s in raw.split("\r") if s]
        msg = {}
        for seg in segments:
            parts = seg.split("|")
            seg_id = parts[0]
            schema = self._segment_schema.get(seg_id)
            if schema is None:
                if self.strict:
                    self.errors.append(f"unknown segment {seg_id}")
                    continue
                schema = [f"f{i}" for i in range(len(parts) - 1)]
                self._segment_schema[seg_id] = schema  # cache discovered layout for everyone
            msg[seg_id] = self._parse(parts[1:], schema)
        return {"site": self.site_id, "msg": msg, "errors": list(self.errors)}

    def _parse(self, values, schema):
        out = {}
        for i, name in enumerate(schema):
            out[name] = values[i] if i < len(values) else None
        return out
```

