class FeatureFlagService:
    def __init__(self, source="etcd://flags"):
        self.source = source
        self._flags = self._load(source)      # base rollout percentages
        self._overrides = {}                  # runtime A/B overrides, hot-pushed

    def _load(self, source):
        return {"promoted_bids": 50, "new_ranker": 10, "cap_enforce": 100}

    def set_override(self, name, enabled):
        self._overrides[name] = enabled

    def is_enabled(self, name, ctx):
        if name in self._overrides:
            return self._overrides[name]
        pct = self._flags.get(name, 0)
        bucket = hash((name, ctx.get("account_id", 0))) % 100
        return bucket < pct


_service = None

def get_flag_service(source="etcd://flags"):
    global _service
    if _service is None:
        _service = FeatureFlagService(source)
    return _service
```

