We have a report-export inheritance tower: `BaseExporter` -> `TabularExporter` -> `CsvExporter`/`XlsxExporter`, plus a `__init_subclass__` registry that maps format names to classes (the web layer looks up `EXPORTERS["csv"]`). Adding "the same table but emailed vs. saved to S3" forced a combinatorial explosion of subclasses. Refactor destination-vs-format into composition, but KEEP the `EXPORTERS` registry populated for every format name and keep `get_exporter(fmt).export(rows, sink)` working. Python 3.11+, stdlib only, no behaviour change to CSV/XLSX bytes.

```python
import csv, io

EXPORTERS = {}

class BaseExporter:
    format_name = None

    def __init_subclass__(cls, **kw):
        super().__init_subclass__(**kw)
        if cls.format_name:
            EXPORTERS[cls.format_name] = cls

    def export(self, rows, sink):
        payload = self.render(rows)
        sink.write(payload)
        return len(payload)

    def render(self, rows):
        raise NotImplementedError

class TabularExporter(BaseExporter):
    def _headers(self, rows):
        return list(rows[0].keys()) if rows else []

class CsvExporter(TabularExporter):
    format_name = "csv"
    def render(self, rows):
        buf = io.StringIO()
        w = csv.writer(buf)
        headers = self._headers(rows)
        w.writerow(headers)
        for r in rows:
            w.writerow([r.get(h, "") for h in headers])
        return buf.getvalue().encode()

class XlsxExporter(TabularExporter):
    format_name = "xlsx"
    def render(self, rows):
        headers = self._headers(rows)
        lines = ["\t".join(headers)]
        for r in rows:
            lines.append("\t".join(str(r.get(h, "")) for h in headers))
        return ("\n".join(lines)).encode()

def get_exporter(fmt):
    return EXPORTERS[fmt]()
```

