from datetime import date

class InventoryHold:
    _hold_seq = 0  # class-level; assigns increasing ids across all instances

    def __init__(self, room_id, start: date, end: date, rate_cents=0):
        InventoryHold._hold_seq += 1
        self.hold_id = InventoryHold._hold_seq
        self.room_id = room_id
        self.start = start
        self.end = end
        self.rate_cents = rate_cents
        self.confirmed = False

    def nights(self):
        return (self.end - self.start).days

    def total_cents(self):
        return self.nights() * self.rate_cents

    def overlaps(self, other):
        return self.room_id == other.room_id and self.start < other.end and other.start < self.end

