Our sensor ingest reads from Kafka and batch-writes to Timescale. During a broker reconnect storm the consumer replays hard, the in-process queue (unbounded) balloons and RSS hits 12GB before the pod OOMs. Worse, the 8 writer threads each call `consumer.commit()` — `confluent_kafka.Consumer` is not thread-safe, and a fast writer can commit an offset past records a slow writer hasn't persisted yet, so a rebalance silently eats data.

```python
import json
import queue
import threading
import time

from confluent_kafka import Consumer

from .db import DBError


class SensorIngest:
    def __init__(self, db, brokers):
        self.db = db
        self.consumer = Consumer({
            "bootstrap.servers": brokers,
            "group.id": "sensor-ingest",
            "enable.auto.commit": False,
        })
        self.consumer.subscribe(["sensors.raw"])
        self.q: queue.Queue = queue.Queue()          # unbounded
        self._stop = threading.Event()
        self._writers = [
            threading.Thread(target=self._writer, daemon=True) for _ in range(8)
        ]
        for t in self._writers:
            t.start()

    def poll_forever(self) -> None:
        while not self._stop.is_set():
            m = self.consumer.poll(0.5)
            if m is None or m.error():
                continue
            self.q.put((m, json.loads(m.value())))   # never blocks

    def _writer(self) -> None:
        while not self._stop.is_set():
            batch = []
            while not self.q.empty() and len(batch) < 500:   # check-then-act
                try:
                    batch.append(self.q.get_nowait())
                except queue.Empty:
                    break
            if not batch:
                time.sleep(0.05)
                continue
            try:
                self.db.write_batch([row for _m, row in batch])   # ~120ms
            except DBError:
                for item in batch:
                    self.q.put(item)                 # requeue: reorders the stream
                time.sleep(1)
                continue
            self.consumer.commit(batch[-1][0])       # 8 threads, one Consumer

    def shutdown(self) -> None:
        self._stop.set()
        for t in self._writers:
            t.join()                                 # unbounded
        self.consumer.close()
```

Refactor. Hard constraints: `poll_forever()` and `shutdown()` stay **sync** and `poll_forever()` keeps running on the main thread — `Consumer` must be touched from exactly one thread, ever; bound the in-process queue at 10_000 and apply real backpressure: when it fills, `pause()` the assignment and *keep calling `poll()`* (we must not be evicted from the group), `resume()` when it drains below half; at-least-once must hold — never commit an offset unless every record below it is durably written; batches of up to 500 records or 200ms, whichever first; at most 4 concurrent DB writers; `shutdown()` must return within 5s; no new third-party deps; Python 3.11+.

`adjudicate()` is the hot path of our claims engine. The dict it returns is our public wire format: it goes straight to Kafka and six downstream consumers (including a Java one that reads fields positionally out of the JSON) depend on the exact key set *and* key order. Two behaviours are load-bearing and undocumented: `reason` is omitted entirely when there is no reason, and `manual_review` is echoed back **only if the key was present on the input** — where `None` means "an adjuster looked and couldn't decide", which is different from the key being absent.

```python
# claims/adjudicate.py -- written 2016, never typed, never touched since
LIMITS = {"dental": 1500, "vision": 400, "medical": 25000}

def _amount(li):
    if isinstance(li, dict):
        return float(li.get("amt", 0))
    if isinstance(li, (list, tuple)):
        return float(li[1])
    if isinstance(li, (int, float)):
        return float(li)
    if isinstance(li, str):
        return float(li)
    raise TypeError("bad line item: %r" % (li,))

def _code(li, i):
    if isinstance(li, dict):
        return li.get("code") or "UNKNOWN"
    if isinstance(li, (list, tuple)):
        return li[0]
    return "LINE%d" % i

def adjudicate(claim):
    out = {}
    out["claim_id"] = claim["claim_id"]
    plan = claim.get("member", {}).get("plan", {}).get("kind", "medical")
    total = 0.0
    lines = []
    for i, li in enumerate(claim.get("lines") or []):
        amt = _amount(li)
        total += amt
        lines.append({"code": _code(li, i), "amt": round(amt, 2)})
    out["plan"] = plan
    out["lines"] = lines
    out["total"] = round(total, 2)
    limit = LIMITS.get(plan, 0)
    if claim.get("member", {}).get("status") != "active":
        st, reason = "denied", "member_inactive"
    elif total > limit:
        st, reason = "pended", "over_limit"
    elif claim.get("flags", {}).get("fraud_score", 0) >= 80:
        st, reason = "pended", "fraud_review"
    else:
        st, reason = "approved", None
    out["status"] = st
    if reason is not None:
        out["reason"] = reason
    if "manual_review" in claim:
        out["manual_review"] = claim["manual_review"]  # True / False / None
    return out
```

Refactor this into properly typed domain objects — enums for the plan kind and the status, a real line-item type instead of the `isinstance` ladder, a `match` for the decision. Constraints: `adjudicate(claim: dict) -> dict` keeps its signature and accepts exactly the same inputs; `json.dumps` of the result must be byte-identical to today's, key order included; `mypy --strict` must pass; stdlib only (no pydantic), Python 3.11+.

response:
Plan: three types (`PlanKind`, `ClaimStatus`, `LineItem`), one `Decision` aggregate, and a parsing layer that absorbs the polymorphic input. The two fragile behaviours — omitted `reason` and the tri-state `manual_review` — get explicit representations: `reason` is `ClaimStatus`-derived and `Optional`, and `manual_review` uses a `MISSING` sentinel so "key absent" and "key present but null" stay distinguishable. Key order is preserved by building the output dict in the original insertion sequence.

```python
from __future__ import annotations

from dataclasses import dataclass
from enum import StrEnum
from typing import Any, Final, Literal, Sequence


class Missing:
    """Sentinel: the key was not present at all (distinct from JSON null)."""
    __slots__ = ()
    def __repr__(self) -> str:
        return "MISSING"


MISSING: Final = Missing()


class PlanKind(StrEnum):
    DENTAL = "dental"
    VISION = "vision"
    MEDICAL = "medical"

    @property
    def limit(self) -> float:
        return _LIMITS[self]


_LIMITS: Final[dict[PlanKind, float]] = {
    PlanKind.DENTAL: 1500.0,
    PlanKind.VISION: 400.0,
    PlanKind.MEDICAL: 25000.0,
}


class ClaimStatus(StrEnum):
    APPROVED = "approved"
    DENIED = "denied"
    PENDED = "pended"


class DenialReason(StrEnum):
    MEMBER_INACTIVE = "member_inactive"
    OVER_LIMIT = "over_limit"
    FRAUD_REVIEW = "fraud_review"


@dataclass(frozen=True, slots=True)
class LineItem:
    code: str
    amount: float

    @classmethod
    def parse(cls, raw: Any, index: int) -> LineItem:
        match raw:
            case {"amt": _} | dict():
                amt = float(raw.get("amt", 0))
                return cls(code=raw.get("code") or "UNKNOWN", amount=amt)
            case [code, amt, *_]:
                return cls(code=code, amount=float(amt))
            case int() | float() | str():
                return cls(code=f"LINE{index}", amount=float(raw))
            case _:
                raise TypeError(f"bad line item: {raw!r}")

    def to_dict(self) -> dict[str, Any]:
        return {"code": self.code, "amt": round(self.amount, 2)}


@dataclass(frozen=True, slots=True)
class Decision:
    claim_id: str
    plan: PlanKind
    lines: tuple[LineItem, ...]
    status: ClaimStatus
    reason: DenialReason | None
    manual_review: bool | None | Missing

    @property
    def total(self) -> float:
        return sum((li.amount for li in self.lines), 0.0)

    def to_dict(self) -> dict[str, Any]:
        # Insertion order below IS the wire contract.
        out: dict[str, Any] = {
            "claim_id": self.claim_id,
            "plan": self.plan.value,
            "lines": [li.to_dict() for li in self.lines],
            "total": round(self.total, 2),
            "status": self.status.value,
        }
        if self.reason is not None:
            out["reason"] = self.reason.value
        if not isinstance(self.manual_review, Missing):
            out["manual_review"] = self.manual_review
        return out


def _decide(active: bool, total: float, plan: PlanKind, fraud: float
            ) -> tuple[ClaimStatus, DenialReason | None]:
    match (active, total > plan.limit, fraud >= 80):
        case (False, _, _):
            return ClaimStatus.DENIED, DenialReason.MEMBER_INACTIVE
        case (_, True, _):
            return ClaimStatus.PENDED, DenialReason.OVER_LIMIT
        case (_, _, True):
            return ClaimStatus.PENDED, DenialReason.FRAUD_REVIEW
        case _:
            return ClaimStatus.APPROVED, None


def _plan_of(claim: dict[str, Any]) -> PlanKind:
    kind = claim.get("member", {}).get("plan", {}).get("kind", "medical")
    try:
        return PlanKind(kind)
    except ValueError:
        # Unknown plan strings had limit 0 (LIMITS.get(plan, 0)) -> always pended.
        return _UnknownPlan(kind)  # type: ignore[return-value]


class _UnknownPlan(str):
    """Preserves the original spelling while behaving like a 0-limit plan."""
    __slots__ = ()
    limit: float = 0.0
    @property
    def value(self) -> str:
        return str(self)


def adjudicate(claim: dict[str, Any]) -> dict[str, Any]:
    plan = _plan_of(claim)
    raw_lines: Sequence[Any] = claim.get("lines") or []
    lines = tuple(LineItem.parse(li, i) for i, li in enumerate(raw_lines))
    total = round(sum((li.amount for li in lines), 0.0), 2)
    active = claim.get("member", {}).get("status") == "active"
    fraud = float(claim.get("flags", {}).get("fraud_score", 0))
    status, reason = _decide(active, total, plan, fraud)  # type: ignore[arg-type]
    return Decision(
        claim_id=claim["claim_id"],
        plan=plan,  # type: ignore[arg-type]
        lines=lines,
        status=status,
        reason=reason,
        manual_review=claim.get("manual_review", MISSING),
    ).to_dict()
```

**Preserved:** key order (`claim_id, plan, lines, total, status, reason?, manual_review?`); `reason` omitted when the claim is clean; `manual_review` echoed only when the key existed, with `None` surviving as JSON `null` via the `MISSING` sentinel; the `> limit` (strict) comparison and the `>= 80` fraud threshold; `round(..., 2)` on floats so no `Decimal` re-formatting sneaks in; unknown plan strings keep their 0 limit and their original spelling.

**Changed:** the `isinstance` ladder is a `match` on `LineItem.parse`; `_decide` is total over the three flags; the total is now derived from the line items rather than accumulated in a loop (same float addition order, so the same result).

