```python
class PluginMeta(type):
    registry = []

    def __init__(cls, name, bases, ns):
        super().__init__(name, bases, ns)
        # the base itself and any class marked abstract must not register
        if not ns.get("abstract", False) and bases:
            PluginMeta.registry.append(cls)


class Plugin(metaclass=PluginMeta):
    abstract = True

    def handles(self, event) -> bool:
        raise NotImplementedError


class EmailPlugin(Plugin):
    def handles(self, event): return event.kind == "email"


class SmsPlugin(Plugin):
    def handles(self, event): return event.kind == "sms"
```

