```python
class RouteMeta(type):
    _plugins = []

    def __init__(cls, name, bases, ns):
        super().__init__(name, bases, ns)
        if bases:
            RouteMeta._plugins.append(cls)


class RoutePlugin(metaclass=RouteMeta):
    pattern = ""
    def matches(self, path: str) -> bool: ...


class AdminRoutes(RoutePlugin):        # defined first -> shadows Catchall
    def matches(self, path): return path.startswith("/admin")


class CatchallRoutes(RoutePlugin):     # broad, must lose to AdminRoutes
    def matches(self, path): return path.startswith("/")


def resolve(path):
