Plan: pull the two hidden dependencies (wall clock, entropy) behind `Protocol`s, move the logic into a `TokenIssuer` value object, and keep the module-level functions as a thin facade so the existing import sites and the fixture generator do not change. The default entropy implementation keeps the exact `getrandbits(8)`-per-byte loop — that is what pins the golden file (`Random.randbytes(16)` would produce a *different* stream from the same seed, so it is off the table).

```python
# auth/tokens.py
from __future__ import annotations

import base64
import hashlib
import os
import random
import time
from dataclasses import dataclass, field
from typing import Protocol, Sequence

TOKEN_TTL_SECONDS = 3600


class TokenError(Exception):
    pass


class Clock(Protocol):
    def now(self) -> float:
        """Seconds since the Unix epoch (UTC)."""


class EntropySource(Protocol):
    def random_bytes(self, n: int) -> bytes: ...


class SystemClock:
    def now(self) -> float:
        return time.time()          # epoch semantics are part of the token format


@dataclass
class RandomEntropy:
    """Byte-for-byte identical to the old _entropy(): one getrandbits(8) per byte."""

    rng: random.Random = field(default_factory=random.Random)

    def random_bytes(self, n: int) -> bytes:
        return bytes(self.rng.getrandbits(8) for _ in range(n))

    @classmethod
    def seeded(cls, seed: object) -> "RandomEntropy":
        return cls(random.Random(seed))


@dataclass(frozen=True)
class TokenIssuer:
    secret: str
    clock: Clock = SystemClock()                       # stateless, safe to share
    entropy: EntropySource = field(default_factory=RandomEntropy)
    default_ttl: int = TOKEN_TTL_SECONDS

    def issue(self, user_id, ttl=None, scopes: Sequence[str] | None = None) -> str:
        ttl = self.default_ttl if ttl is None else ttl
        issued_at = int(self.clock.now())
        expires_at = issued_at + ttl
        nonce = self.entropy.random_bytes(16)
        payload = "%s|%d|%d|%s" % (user_id, issued_at, expires_at, ",".join(scopes or []))
        mac = hashlib.sha256((self.secret + payload).encode() + nonce).hexdigest()
        raw = payload.encode() + b"|" + base64.b16encode(nonce) + b"|" + mac.encode()
        return base64.urlsafe_b64encode(raw).decode().rstrip("=")

    def verify(self, token: str) -> dict:
        pad = "=" * (-len(token) % 4)
        raw = base64.urlsafe_b64decode(token + pad)
        parts = raw.split(b"|")
        if len(parts) != 6:
            raise TokenError("malformed")
        user_id, issued_at, expires_at, scopes, nonce_b16, mac = parts
        nonce = base64.b16decode(nonce_b16)
        payload = b"|".join(parts[:4]).decode()
        expected = hashlib.sha256((self.secret + payload).encode() + nonce).hexdigest()
        if expected != mac.decode():
            raise TokenError("bad signature")
        if int(self.clock.now()) > int(expires_at):
            raise TokenError("expired")
        return {
            "user_id": user_id.decode(),
            "issued_at": int(issued_at),
            "expires_at": int(expires_at),
            "scopes": scopes.decode().split(",") if scopes else [],
        }


# --- module facade: unchanged public surface -------------------------------
_default: TokenIssuer | None = None


def _issuer() -> TokenIssuer:
    global _default
    if _default is None:
        _default = TokenIssuer(secret=os.environ.get("SESSION_SECRET", "dev-secret"))
    return _default


def issue_token(user_id, ttl=None, scopes=None):
    return _issuer().issue(user_id, ttl, scopes)


def verify_token(token):
    return _issuer().verify(token)


def seed_for_fixtures(seed):
    global _default
    _default = TokenIssuer(
        secret=os.environ.get("SESSION_SECRET", "dev-secret"),
        entropy=RandomEntropy.seeded(seed),
    )
```

What I preserved: the wire format, the epoch-second `issued_at`/`expires_at`, the positional signature of `issue_token`, the returned plain `dict` (callers still mutate it — I did not freeze it), and the seeded nonce stream (same `getrandbits(8)` loop, same 16 calls per token).

What changed: `SESSION_SECRET` is now read on first use instead of at import, so importing `auth.tokens` no longer snapshots the environment; the logic lives in `TokenIssuer`, which takes its dependencies as arguments.

```python
def test_expiry_is_epoch_relative():
    class FixedClock:
        def now(self): return 1_700_000_000.0
    class ZeroEntropy:
        def random_bytes(self, n): return b"\x00" * n

    issuer = TokenIssuer("s3cret", clock=FixedClock(), entropy=ZeroEntropy())
    claims = issuer.verify(issuer.issue("u1", 60, ["read"]))
    assert claims["expires_at"] == 1_700_000_060
```

Plan: three layers. `render_*` are pure `list[dict] -> str`. `write_atomic` is the only thing that talks to the disk. `export_csv` / `export_json` / `export_ndjson` are the new public API and compose the two. `export()` becomes a shim that validates `mode` first, warns with `stacklevel=2`, and dispatches — so every existing positional call keeps its exact behaviour and return shape.

```python
# reportkit/export.py
from __future__ import annotations

import csv
import gzip
import io
import json
import os
import warnings
from typing import Any, Iterable, Mapping, Sequence

Record = Mapping[str, Any]

_MODES = {"csv": "csv", "json": "json", "jsonl": "jsonl", "ndjson": "jsonl"}


# --- pure core: no filesystem, no globals ----------------------------------
def render_csv(records: Sequence[Record], *, delimiter: str = ",",
               fieldnames: Sequence[str] | None = None) -> str:
    buf = io.StringIO()
    names = (fieldnames or list(records[0].keys())) if records else (fieldnames or [])
    w = csv.DictWriter(buf, fieldnames=names, delimiter=delimiter, extrasaction="ignore")
    w.writeheader()
    for r in records:
        w.writerow(r)
    return buf.getvalue()


def render_json(records: Sequence[Record], *, indent: int | None = None) -> str:
    return json.dumps(records, indent=indent, default=str)


def render_ndjson(records: Iterable[Record]) -> str:
    return "".join(json.dumps(r, default=str) + "\n" for r in records)


# --- imperative shell: the only I/O in the module --------------------------
def write_atomic(path: str, raw: bytes) -> int:
    tmp = path + ".tmp"
    with open(tmp, "wb") as fh:
        fh.write(raw)
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, path)
    return len(raw)


def _emit(text: str, path: str | None, compress: bool) -> bytes | int:
    raw = text.encode("utf-8")
    if compress:
        raw = gzip.compress(raw)
    if path is None:
        return raw
    return write_atomic(path, raw)


# --- new API ---------------------------------------------------------------
def export_csv(records, path=None, *, delimiter=",", compress=False, fieldnames=None):
    return _emit(render_csv(records, delimiter=delimiter, fieldnames=fieldnames),
                 path, compress)


def export_json(records, path=None, *, indent=None, compress=False):
    return _emit(render_json(records, indent=indent), path, compress)


def export_ndjson(records, path=None, *, compress=False):
    return _emit(render_ndjson(records), path, compress)


# --- 2.x shim: same signature, same semantics, same return shapes ----------
def export(records, mode="csv", path=None, delimiter=",", indent=None,
           compress=False, fieldnames=None):
    canonical = _MODES.get(mode)
    if canonical is None:
        raise ValueError("unknown mode: %r" % (mode,))          # still raises first
    warnings.warn(
        "export(mode=...) is deprecated and will be removed in 3.0; "
        "use export_%s() instead" % canonical,
        DeprecationWarning,
        stacklevel=2,                                            # -> the caller's line
    )
    if canonical == "csv":
        return export_csv(records, path, delimiter=delimiter, compress=compress,
                          fieldnames=fieldnames)
    if canonical == "json":
        return export_json(records, path, indent=indent, compress=compress)
    return export_ndjson(records, path, compress=compress)
```

What I preserved: `export`'s parameter names, order and defaults (so `export(rows, "json", "/tmp/o.json")` still works positionally); validation of `mode` *before* touching `records`; the `ndjson` -> `jsonl` alias; the empty-records CSV path (`DictWriter(fieldnames=[])` still emits a bare newline); the gzip step running *after* rendering and *before* the size is measured; and the dual return type (`bytes` with no `path`, `len(raw)` with one).

What changed: `mode` is deprecated (it still works, it just warns at the caller); the renderers are pure and unit-testable with no `tmp_path`; the only `open()` in the module now lives in `write_atomic`.

```python
def test_ndjson_render_is_pure():
    assert render_ndjson([{"a": 1}, {"a": 2}]) == '{"a": 1}\n{"a": 2}\n'

def test_shim_still_returns_bytes_and_warns_at_caller():
    with pytest.warns(DeprecationWarning):
        assert export([{"a": 1}], "jsonl") == b'{"a": 1}\n'
```

