This is our public SDK client (PyPI, ~400 dependent repos). We are replacing the `retries=` / `backoff=` knobs with a single `retry_policy=RetryPolicy(...)` object, deprecating the old kwargs over two releases — they must keep **working**, not merely warn, for all of 4.x. Our own tests are three stacked `@mock.patch` decorators around `urlopen` and `time.sleep`, and we want them gone.

```python
# sdk/client.py
import json
import time
import urllib.error
import urllib.request


class ApiClient:
    def __init__(self, base_url, *, token=None, timeout=10.0, retries=3, backoff=0.5):
        self.base_url = base_url.rstrip("/")
        self.token = token
        self.timeout = timeout
        self.retries = retries
        self.backoff = backoff

    def _url(self, path):
        return self.base_url + "/" + path.lstrip("/")

    def request(self, method, path, body=None):
        data = json.dumps(body).encode() if body is not None else None
        req = urllib.request.Request(self._url(path), data=data, method=method)
        req.add_header("content-type", "application/json")
        if self.token:
            req.add_header("authorization", "Bearer " + self.token)

        last = None
        for attempt in range(self.retries + 1):
            try:
                with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                    return json.loads(resp.read() or b"null")
            except urllib.error.HTTPError as e:
                if e.code < 500 and e.code != 429:
                    raise
                last = e
            except urllib.error.URLError as e:
                last = e
            if attempt < self.retries:
                time.sleep(self.backoff * (2 ** attempt))
        raise last

    def get(self, path):
        return self.request("GET", path)

    def post(self, path, body):
        return self.request("POST", path, body)
```

