response:
Plan: (1) a `RetryPolicy` dataclass, (2) `Transport` and `Sleeper` protocols with urllib/time adapters as defaults, (3) a small reusable `@_deprecated_kwargs` decorator that handles the 4.x compatibility surface in one place instead of scattering `if retries is not _UNSET` blocks through `__init__`.

```python
# sdk/client.py
from __future__ import annotations

import functools
import json
import time
import urllib.error
import urllib.request
import warnings
from dataclasses import dataclass
from typing import Any, Mapping, Protocol


@dataclass(frozen=True)
class RetryPolicy:
    attempts: int = 3          # number of *retries* after the first try
    backoff: float = 0.5       # base delay; grows as backoff * 2**attempt

    def delay_for(self, attempt: int) -> float:
        return self.backoff * (2 ** attempt)


class Response(Protocol):
    status: int
    body: bytes


class Transport(Protocol):
    def send(self, method: str, url: str, *, headers: Mapping[str, str],
             body: bytes | None, timeout: float) -> Response: ...


class Sleeper(Protocol):
    def sleep(self, seconds: float) -> None: ...


class TimeSleeper:
    def sleep(self, seconds: float) -> None:
        time.sleep(seconds)


class UrllibTransport:
    def send(self, method, url, *, headers, body, timeout):
        req = urllib.request.Request(url, data=body, method=method)
        for k, v in headers.items():
            req.add_header(k, v)
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return _Resp(resp.status, resp.read())


@dataclass
class _Resp:
    status: int
    body: bytes


def _deprecated_kwargs(**mapping: str):
    """Warn (at the caller's frame) for kwargs that moved somewhere else."""
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for old, new in mapping.items():
                if old in kwargs:
                    warnings.warn(
                        f"{old}= is deprecated and will be removed in 5.0; use {new}=",
                        DeprecationWarning,
                        stacklevel=2,
                    )
                    kwargs.pop(old)
            return fn(*args, **kwargs)
        return wrapper
    return deco


class ApiClient:
    @_deprecated_kwargs(retries="retry_policy", backoff="retry_policy")
    def __init__(self, base_url, *, token=None, timeout=10.0,
                 retry_policy: RetryPolicy | None = None,
                 transport: Transport | None = None,
                 sleeper: Sleeper | None = None):
        self.base_url = base_url.rstrip("/")
        self.token = token
        self.timeout = timeout
        self.retry_policy = retry_policy or RetryPolicy()
        self.transport: Transport = transport or UrllibTransport()
        self.sleeper: Sleeper = sleeper or TimeSleeper()

    def _url(self, path: str) -> str:
        return self.base_url + "/" + path.lstrip("/")

    def request(self, method: str, path: str, body: Any = None):
        data = json.dumps(body).encode() if body is not None else None
        headers = {"content-type": "application/json"}
        if self.token:
            headers["authorization"] = "Bearer " + self.token

        policy = self.retry_policy
        last: BaseException | None = None
        for attempt in range(policy.attempts + 1):
            try:
                resp = self.transport.send(method, self._url(path), headers=headers,
                                           body=data, timeout=self.timeout)
                return json.loads(resp.body or b"null")
            except urllib.error.HTTPError as e:
                if e.code < 500 and e.code != 429:
                    raise
                last = e
            except urllib.error.URLError as e:
                last = e
            if attempt < policy.attempts:
                self.sleeper.sleep(policy.delay_for(attempt))
        raise last

    def get(self, path):
        return self.request("GET", path)

    def post(self, path, body):
        return self.request("POST", path, body)
```

What I preserved: `base_url` stays positional; only 5xx and 429 are retried, 4xx still raises immediately; the backoff curve is still `base * 2**attempt` and the last delay is skipped; the last exception is re-raised, not swallowed. Unknown kwargs still hit `__init__`'s real signature, so `retires=5` raises `TypeError` exactly as before.

What changed: no `urlopen` or `time.sleep` reachable from the retry loop — pass a fake `Transport`/`Sleeper` and assert on the recorded delays.

```python
def test_backoff_curve():
    class Boom:
        def send(self, *a, **k): raise urllib.error.URLError("down")
    class RecSleeper:
        def __init__(self): self.calls = []
        def sleep(self, s): self.calls.append(s)

    s = RecSleeper()
    c = ApiClient("http://x", retry_policy=RetryPolicy(attempts=3, backoff=1.0),
                  transport=Boom(), sleeper=s)
    with pytest.raises(urllib.error.URLError):
        c.get("/ping")
    assert s.calls == [1.0, 2.0, 4.0]
```

Plan: a frozen `Settings` dataclass with a `from_env()` constructor, a `Transport` protocol with a urllib adapter, and an `AnalyticsClient` that owns its own buffer. The module keeps `track`/`flush` as a facade over a lazily-created default client, so nothing downstream changes.

```python
# analytics/client.py
from __future__ import annotations

import json
import os
import urllib.request
from dataclasses import dataclass, field
from typing import Any, Mapping, Protocol


@dataclass(frozen=True)
class Settings:
    api_base: str
    api_key: str
    timeout: float = 5.0
    flush_every: int = 20

    @classmethod
    def from_env(cls, env: Mapping[str, str] | None = None) -> "Settings":
        env = os.environ if env is None else env
        return cls(
            api_base=env["ANALYTICS_API_BASE"],
            api_key=env["ANALYTICS_API_KEY"],
            timeout=float(env.get("ANALYTICS_TIMEOUT", "5")),
            flush_every=int(env.get("ANALYTICS_FLUSH_EVERY", "20")),
        )


class Transport(Protocol):
    def post(self, url: str, *, body: bytes, headers: Mapping[str, str],
             timeout: float) -> None: ...


class UrllibTransport:
    def post(self, url, *, body, headers, timeout) -> None:
        req = urllib.request.Request(url, data=body, method="POST")
        for k, v in headers.items():
            req.add_header(k, v)
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            resp.read()


DEFAULT_SETTINGS = Settings.from_env()


@dataclass
class AnalyticsClient:
    settings: Settings = DEFAULT_SETTINGS
    transport: Transport = field(default_factory=UrllibTransport)
    _buffer: list[dict[str, Any]] = field(default_factory=list, init=False)

    def track(self, event: str, props: dict | None = None,
              user_id: str | None = None) -> int:
        self._buffer.append({"event": event, "props": props or {}, "user_id": user_id})
        if len(self._buffer) >= self.settings.flush_every:
            return self.flush()
        return 0

    def flush(self) -> int:
        if not self._buffer:
            return 0
        batch = self._buffer
        self._buffer = []                       # swap first: a failing POST cannot
        payload = json.dumps({"batch": batch}).encode()   # double-send on retry
        self.transport.post(
            self.settings.api_base + "/v1/batch",
            body=payload,
            headers={"authorization": "Bearer " + self.settings.api_key,
                     "content-type": "application/json"},
            timeout=self.settings.timeout,
        )
        return len(batch)


# --- module facade: existing callers keep working --------------------------
_default: AnalyticsClient | None = None


def _client() -> AnalyticsClient:
    global _default
    if _default is None:
        _default = AnalyticsClient()
    return _default


def track(event, props=None, user_id=None):
    return _client().track(event, props, user_id)


def flush():
    return _client().flush()


def reset_default_client() -> None:
    """Test hook: drop the process-wide client (and its buffer)."""
    global _default
    _default = None
```

What I preserved: `track(event, props=None, user_id=None)` and `flush()` keep their signatures and return values (number of events flushed, `0` when nothing was sent); the auto-flush threshold semantics; the batch wire format `{"batch": [...]}`; the same headers and endpoint path.

What changed: every dependency is a constructor argument; each `AnalyticsClient` owns its buffer, so tests no longer bleed into each other; `flush()` empties the buffer before the POST rather than after, which removes a duplicate-send window.

```python
def test_env_is_picked_up_without_reload(monkeypatch):
    monkeypatch.setenv("ANALYTICS_API_BASE", "http://x")
    monkeypatch.setenv("ANALYTICS_API_KEY", "k")

    class FakeTransport:
        sent = []
        def post(self, url, *, body, headers, timeout): FakeTransport.sent.append(url)

    c = AnalyticsClient(settings=Settings.from_env(), transport=FakeTransport())
    c.track("signup")
    assert c.flush() == 1
    assert FakeTransport.sent == ["http://x/v1/batch"]
```

Plan: three seams — `Clock` (epoch seconds), `RandomSource` (`getrandbits`, so the seeded stream is preserved bit for bit) and `Sequence` (the counter). `KeyFactory` holds them plus the namespace; the module keeps `new_key`/`seed` as a facade over a lazily-built default factory so nothing downstream changes and the env var is read on first use, not at import.

```python
# payments/idempotency.py
from __future__ import annotations

import hashlib
import os
import random
import threading
import time
import uuid
from dataclasses import dataclass, field
from typing import Protocol

DEFAULT_NAMESPACE = "prod"


class Clock(Protocol):
    def now(self) -> float:
        """Seconds since the Unix epoch."""


class RandomSource(Protocol):
    def getrandbits(self, k: int) -> int: ...


class Sequence(Protocol):
    def next(self) -> int: ...


class SystemClock:
    def now(self) -> float:
        return time.time()          # epoch, not monotonic: the day bucket depends on it


class ThreadLocalRandom:
    """Per-thread random.Random, exactly as before. seed() replaces this thread's."""

    def __init__(self) -> None:
        self._local = threading.local()

    def _rng(self) -> random.Random:
        rnd = getattr(self._local, "rnd", None)
        if rnd is None:
            rnd = random.Random(uuid.uuid4().int ^ os.getpid() ^ time.time_ns())
            self._local.rnd = rnd
        return rnd

    def getrandbits(self, k: int) -> int:
        return self._rng().getrandbits(k)

    def seed(self, value: object) -> None:
        self._local.rnd = random.Random(value)


class AtomicCounter:
    def __init__(self, start: int = 0) -> None:
        self._value = start
        self._lock = threading.Lock()

    def next(self) -> int:
        with self._lock:
            self._value += 1
            return self._value


@dataclass
class KeyFactory:
    namespace: str = DEFAULT_NAMESPACE
    clock: Clock = field(default_factory=SystemClock)
    rng: RandomSource = field(default_factory=ThreadLocalRandom)
    counter: Sequence = field(default_factory=AtomicCounter)

    @classmethod
    def from_env(cls, env=None, **overrides) -> "KeyFactory":
        env = os.environ if env is None else env
        return cls(namespace=env.get("IDEMPOTENCY_NAMESPACE", DEFAULT_NAMESPACE),
                   **overrides)

    def day_bucket(self) -> int:
        return int(self.clock.now()) // 86400

    def new_key(self, tenant_id, request_fingerprint=None) -> str:
        day = self.day_bucket()
        if request_fingerprint is not None:
            material = "%s:%s:%s:%d" % (self.namespace, tenant_id,
                                        request_fingerprint, day)
            return hashlib.sha256(material.encode()).hexdigest()[:32]
        return "%s-%d-%06d-%08x" % (tenant_id, day, self.counter.next(),
                                    self.rng.getrandbits(32))


# --- module facade ---------------------------------------------------------
_default: KeyFactory | None = None


def _factory() -> KeyFactory:
    global _default
    if _default is None:
        _default = KeyFactory.from_env()      # env read on first use
    return _default


def new_key(tenant_id, request_fingerprint=None):
    return _factory().new_key(tenant_id, request_fingerprint)


def seed(value):
    rng = _factory().rng
    if not isinstance(rng, ThreadLocalRandom):
        raise TypeError("seed() only applies to the default ThreadLocalRandom source")
    rng.seed(value)


def reset_default_factory() -> None:
    global _default
    _default = None
```

What I preserved: both key formats character-for-character (`sha256(...)[:32]` for the deterministic branch, `tenant-day-%06d-%08x` for the random one); the epoch day bucket; the `getrandbits(32)` call — same generator, same call, so a seeded `random.Random(99)` yields the identical stream as the golden file; the counter increments only on the random branch; `new_key` stays positional.

What changed: the counter lives on the factory (`KeyFactory()` per test = fresh sequence), the namespace is read at construction rather than import, and the clock/RNG are arguments.

```python
def test_deterministic_branch_uses_epoch_day():
    class FixedClock:
        def now(self): return 1_700_000_000.0
    f = KeyFactory(namespace="test", clock=FixedClock())
    assert f.new_key("acme", "abc") == f.new_key("acme", "abc")
    assert f.day_bucket() == 1_700_000_000 // 86400

def test_counter_is_per_instance():
    class Zero:
        def getrandbits(self, k): return 0
    f = KeyFactory(rng=Zero(), clock=SystemClock())
    assert f.new_key("acme").split("-")[2] == "000001"
```

