Plan: replace the literal default with a module-private `_UNSET` sentinel so we can distinguish "omitted" from "explicitly False", resolve it in one place, and emit the warning from a small helper that both public entry points share. The sentinel keeps `has_header` in the same positional slot, so `read_table(text, True)` is untouched.

```python
# tabular/reader.py
from __future__ import annotations

import csv
import io
import warnings
from enum import Enum
from typing import Any


class _Unset(Enum):
    """Single-valued enum: gives us a typed, repr-friendly sentinel."""
    TOKEN = object()


_UNSET = _Unset.TOKEN

# 2.x behaviour; becomes True in 3.0
_HAS_HEADER_DEFAULT = False
_HAS_HEADER_FUTURE = True


def _warn_default_change(param: str, current: Any, future: Any) -> None:
    warnings.warn(
        f"{param} was not given; it currently defaults to {current!r}, but the "
        f"default changes to {future!r} in tabular 3.0. Pass {param}={current!r} "
        f"explicitly to keep today's behaviour.",
        DeprecationWarning,
        stacklevel=2,
    )


def _resolve_has_header(has_header: Any) -> bool:
    if has_header is _UNSET:
        _warn_default_change("has_header", _HAS_HEADER_DEFAULT, _HAS_HEADER_FUTURE)
        return _HAS_HEADER_DEFAULT
    return bool(has_header)


# --- pure core: no warnings, no defaults, no I/O ---------------------------
def parse_rows(rows: list[list[str]], *, has_header: bool, coerce: bool) -> list:
    if not rows:
        return []
    if has_header:
        header, body = rows[0], rows[1:]
        out: list = [dict(zip(header, r)) for r in body]
    else:
        out = rows
    if coerce:
        out = [_coerce(r) for r in out]
    return out


def read_table(source, has_header=_UNSET, delimiter=",", coerce=True):
    """source: a CSV string or an open text file. Returns list[list] or list[dict]."""
    resolved = _resolve_has_header(has_header)
    fh = io.StringIO(source) if isinstance(source, str) else source
    rows = [r for r in csv.reader(fh, delimiter=delimiter) if r]
    return parse_rows(rows, has_header=resolved, coerce=coerce)


def read_file(path, has_header=_UNSET, delimiter=",", coerce=True):
    resolved = _resolve_has_header(has_header)
    with open(path, newline="") as fh:
        rows = [r for r in csv.reader(fh, delimiter=delimiter) if r]
    return parse_rows(rows, has_header=resolved, coerce=coerce)


def _coerce(row):
    if isinstance(row, dict):
        return {k: _cell(v) for k, v in row.items()}
    return [_cell(v) for v in row]


def _cell(v):
    v = v.strip()
    if v == "":
        return None
    try:
        return int(v)
    except ValueError:
        pass
    try:
        return float(v)
    except ValueError:
        return v
```

What I preserved: `has_header` stays the second positional parameter, so `read_table(text, True)` is unchanged; explicit `has_header=False` produces the old result with **no** warning; the empty-input `[]` short-circuit; the coercion rules and their `int` -> `float` -> `str` order; `read_file`'s keyword pass-through (it now names the parameters explicitly rather than forwarding `**kwargs`, so it can resolve the sentinel itself instead of double-warning through `read_table`).

What changed: exactly one `DeprecationWarning` per call that omits `has_header`, and the parsing logic is now a pure `parse_rows` that takes a resolved bool — no sentinel, no warnings, trivially unit-testable.

```python
def test_omitted_default_warns_once_and_keeps_old_behaviour(recwarn):
    out = read_table("a,b\n1,2\n")
    assert out == [["a", "b"], [1, 2]]                 # still header-less
    assert len(recwarn.list) == 1

def test_explicit_value_is_silent(recwarn):
    assert read_table("a,b\n1,2\n", has_header=False) == [["a", "b"], [1, 2]]
    assert recwarn.list == []
```

