Our payments retry test is three stacked `@mock.patch` decorators and it broke twice last month when we renamed an internal import path — the mocks patch strings, so nothing type-checks. We want the mocks gone. Careful: the load test seeds the global `random` module (`random.seed(7)`) and asserts the exact jitter delay sequence, so whatever RNG the default path uses must still be the *module-level* `random` instance.

```python
# billing/processor.py
import json
import random
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

GATEWAY = "https://pay.example.com/v2/charges"


def charge(card_token, amount_cents, currency="EUR", idempotency_key=None, attempts=4):
    body = json.dumps({"card": card_token, "amount": amount_cents,
                       "currency": currency}).encode()
    delay = 0.25
    for i in range(attempts):
        req = urllib.request.Request(GATEWAY, data=body, method="POST")
        req.add_header("idempotency-key", idempotency_key or "")
        req.add_header("content-type", "application/json")
        try:
            with urllib.request.urlopen(req, timeout=8) as resp:
                payload = json.loads(resp.read())
            return {"status": "ok", "id": payload["id"],
                    "captured_at": datetime.now(timezone.utc).isoformat()}
        except urllib.error.HTTPError as e:
            if e.code == 409:
                return {"status": "duplicate", "id": None,
                        "captured_at": datetime.now(timezone.utc).isoformat()}
            if e.code < 500:
                raise
        except urllib.error.URLError:
            pass
        if i < attempts - 1:
            time.sleep(delay + random.uniform(0, delay))     # full jitter
            delay *= 2
    return {"status": "failed", "id": None,
            "captured_at": datetime.now(timezone.utc).isoformat()}
```

