response:
Plan: four ports — `Transport`, `Sleeper`, `Clock`, `Jitter` — and a `PaymentProcessor` that contains the retry policy. The default `Jitter` deliberately delegates to the *module-level* `random` functions rather than owning a private `random.Random`, because the load test seeds the global generator and asserts the exact delay sequence; a fresh `Random()` would silently decouple from `random.seed(7)`. `charge()` stays as a module function so existing call sites are untouched.

```python
# billing/processor.py
from __future__ import annotations

import json
import random
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any, Mapping, Protocol

GATEWAY = "https://pay.example.com/v2/charges"


class HttpError(Exception):
    def __init__(self, code: int) -> None:
        super().__init__(code)
        self.code = code


class NetworkError(Exception):
    pass


class Transport(Protocol):
    def post(self, url: str, *, body: bytes, headers: Mapping[str, str],
             timeout: float) -> bytes:
        """Return the response body, or raise HttpError / NetworkError."""


class Sleeper(Protocol):
    def sleep(self, seconds: float) -> None: ...


class Clock(Protocol):
    def now(self) -> datetime: ...


class Jitter(Protocol):
    def uniform(self, a: float, b: float) -> float: ...


class UrllibTransport:
    def post(self, url, *, body, headers, timeout) -> bytes:
        req = urllib.request.Request(url, data=body, method="POST")
        for k, v in headers.items():
            req.add_header(k, v)
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                return resp.read()
        except urllib.error.HTTPError as e:
            raise HttpError(e.code) from e
        except urllib.error.URLError as e:
            raise NetworkError(str(e)) from e


class TimeSleeper:
    def sleep(self, seconds: float) -> None:
        time.sleep(seconds)


class UtcClock:
    def now(self) -> datetime:
        return datetime.now(timezone.utc)


class GlobalRandomJitter:
    """Uses the module-level `random` instance on purpose: random.seed(7) must
    still pin the delay sequence for the load test."""

    def uniform(self, a: float, b: float) -> float:
        return random.uniform(a, b)


@dataclass
class PaymentProcessor:
    gateway: str = GATEWAY
    transport: Transport = field(default_factory=UrllibTransport)
    sleeper: Sleeper = field(default_factory=TimeSleeper)
    clock: Clock = field(default_factory=UtcClock)
    jitter: Jitter = field(default_factory=GlobalRandomJitter)
    timeout: float = 8.0
    base_delay: float = 0.25

    def _result(self, status: str, charge_id: str | None) -> dict[str, Any]:
        return {"status": status, "id": charge_id,
                "captured_at": self.clock.now().isoformat()}     # plain, mutable dict

    def charge(self, card_token, amount_cents, currency="EUR",
               idempotency_key=None, attempts=4) -> dict[str, Any]:
        body = json.dumps({"card": card_token, "amount": amount_cents,
                           "currency": currency}).encode()
        headers = {"idempotency-key": idempotency_key or "",
                   "content-type": "application/json"}
        delay = self.base_delay
        for i in range(attempts):
            try:
                raw = self.transport.post(self.gateway, body=body, headers=headers,
                                          timeout=self.timeout)
                return self._result("ok", json.loads(raw)["id"])
            except HttpError as e:
                if e.code == 409:
                    return self._result("duplicate", None)
                if e.code < 500:
                    raise
            except NetworkError:
                pass
            if i < attempts - 1:
                self.sleeper.sleep(delay + self.jitter.uniform(0, delay))
                delay *= 2
        return self._result("failed", None)


_default = PaymentProcessor()


def charge(card_token, amount_cents, currency="EUR", idempotency_key=None, attempts=4):
    return _default.charge(card_token, amount_cents, currency, idempotency_key, attempts)
```

What I preserved: `charge`'s positional signature and defaults; the retry classification (409 -> `duplicate`, other 4xx re-raised, 5xx and network errors retried); `delay + uniform(0, delay)` then `delay *= 2`, with no sleep after the final attempt — so with `random.seed(7)` the draws and delays are identical; the result is still a plain `dict` the caller can mutate.

What changed: `urllib`'s exception types no longer leak into the retry logic (the transport translates them into `HttpError`/`NetworkError`), so a fake transport does not need to construct `HTTPError` objects. Note the re-raise for non-409 4xx now surfaces `HttpError`, which subclasses nothing urllib-specific — if a caller catches `urllib.error.HTTPError` today, keep `UrllibTransport` raising the original via `raise ... from e` and catch `HttpError` at the boundary.

```python
def test_retries_then_succeeds():
    class FlakyTransport:
        def __init__(self): self.calls = 0
        def post(self, url, *, body, headers, timeout):
            self.calls += 1
            if self.calls == 1:
                raise NetworkError("down")
            return b'{"id": "ch_1"}'
    class RecSleeper:
        def __init__(self): self.calls = []
        def sleep(self, s): self.calls.append(s)

    sleeper = RecSleeper()
    p = PaymentProcessor(transport=FlakyTransport(), sleeper=sleeper,
                         jitter=type("Z", (), {"uniform": lambda self, a, b: 0.0})())
    assert p.charge("tok", 100)["status"] == "ok"
    assert sleeper.calls == [0.25]
```

Plan: a pure `build_settings(defaults, file_data, env)` function, two tiny ports (`ConfigSource` for the file bytes, plus a plain `Mapping` for the environment), and a `Settings` object that is a `Mapping` so every `cfg["region"]` / `cfg.get(...)` / `in` call site keeps working while we add `schema_version`. Deep-copying the defaults kills the `DEFAULTS` mutation bug.

```python
# config/settings.py
from __future__ import annotations

import copy
import json
import os
from dataclasses import dataclass
from types import MappingProxyType
from typing import Any, Iterator, Mapping, Protocol

SCHEMA_VERSION = 2

DEFAULTS: Mapping[str, Any] = {
    "region": "eu-west-1",
    "timeout_s": 30,
    "feature_flags": {"beta_ui": False, "new_billing": False},
}


class ConfigSource(Protocol):
    def read(self) -> Mapping[str, Any]:
        """Return the parsed config document ({} when absent)."""


class FileConfigSource:
    def __init__(self, path: str) -> None:
        self.path = path

    def read(self) -> Mapping[str, Any]:
        try:
            with open(self.path) as fh:
                return json.load(fh)
        except FileNotFoundError:
            return {}


class DictConfigSource:
    """For tests: no filesystem at all."""

    def __init__(self, doc: Mapping[str, Any] | None = None) -> None:
        self.doc = dict(doc or {})

    def read(self) -> Mapping[str, Any]:
        return self.doc


def _freeze(value: Any) -> Any:
    if isinstance(value, Mapping):
        return MappingProxyType({k: _freeze(v) for k, v in value.items()})
    return value


@dataclass(frozen=True)
class Settings(Mapping):
    """A Mapping, so every existing cfg["region"] / cfg.get(...) / `in` still works."""

    _data: Mapping[str, Any]

    def __getitem__(self, key: str) -> Any:
        return self._data[key]

    def __iter__(self) -> Iterator[str]:
        return iter(self._data)

    def __len__(self) -> int:
        return len(self._data)

    @property
    def schema_version(self) -> int:
        return self._data["schema_version"]

    @property
    def feature_flags(self) -> Mapping[str, bool]:
        return self._data["feature_flags"]


# --- pure core -------------------------------------------------------------
def build_settings(file_data: Mapping[str, Any], env: Mapping[str, str]) -> Settings:
    data: dict[str, Any] = copy.deepcopy(dict(DEFAULTS))     # DEFAULTS never mutated
    data.update(file_data)
    flags = dict(data.get("feature_flags", {}))
    for k, v in env.items():
        if k.startswith("APP_FLAG_"):
            flags[k[len("APP_FLAG_"):].lower()] = v == "1"
    data["feature_flags"] = flags
    data["timeout_s"] = int(data["timeout_s"])
    data["schema_version"] = SCHEMA_VERSION
    return Settings(_freeze(data))


# --- shell -----------------------------------------------------------------
def load_settings(path: str | None = None, *,
                  source: ConfigSource | None = None,
                  env: Mapping[str, str] | None = None) -> Settings:
    env = os.environ if env is None else env
    if source is None:
        source = FileConfigSource(path or env.get("APP_CONFIG", "/etc/app/config.json"))
    return build_settings(source.read(), env)
```

What I preserved: `load_settings(path)` keeps its positional parameter; the merge order (defaults -> file -> `APP_FLAG_*` env overlay); `timeout_s` coerced to `int`; and the whole read surface — `cfg["region"]`, `cfg.get("timeout_s")`, `"feature_flags" in cfg`, `dict(cfg)`, iteration — because `Settings` implements `Mapping`. The admin endpoint keeps reaching `cfg["feature_flags"][name]` exactly as it does today.

What changed: no `_CACHE`, no `_LOCK`, no global mutation — every call builds a fresh value, and `DEFAULTS` is deep-copied so a load can no longer poison the process. `schema_version: 2` is now part of the shape (and reachable as `cfg.schema_version`). Tests inject a `DictConfigSource` and a plain dict for `env`:

```python
def test_env_flag_overlay_without_filesystem():
    cfg = load_settings(source=DictConfigSource({"region": "us-east-1"}),
                        env={"APP_FLAG_BETA_UI": "1"})
    assert cfg["region"] == "us-east-1"
    assert cfg["feature_flags"]["beta_ui"] is True
    assert cfg["timeout_s"] == 30 and cfg.schema_version == 2
    assert DEFAULTS["feature_flags"]["beta_ui"] is False    # defaults untouched
```

